def solve(n: int) -> int:
    """Return the count of primes strictly less than n using a simple sieve.
    n can be up to reasonable limits for this challenge.
    """
    if n <= 2:
        return 0
    import math
    # sieve[i] indicates whether i is prime
    sieve = [True] * n
    sieve[0] = sieve[1] = False
    limit = int(math.isqrt(n - 1))
    for p in range(2, limit + 1):
        if sieve[p]:
            # start marking at p*p
            start = p * p
            for multiple in range(start, n, p):
                sieve[multiple] = False
    return sum(sieve)

