def solve(meetings):
    # Filter valid meetings where start <= end
    intervals = []
    for m in meetings:
        if not isinstance(m, (list, tuple)):
            continue
        if len(m) < 2:
            continue
        s, e = m[0], m[1]
        # Ensure numeric
        if not isinstance(s, (int, float)) or not isinstance(e, (int, float)):
            continue
        if s > e:
            continue  # invalid meeting, ignore
        intervals.append((s, e))
    # Greedy by earliest end time, tie by start
    intervals.sort(key=lambda x: (x[1], x[0]))
    count = 0
    last_end = -float('inf')
    for s, e in intervals:
        if s >= last_end:
            count += 1
            last_end = e
    return count

