def solve(s: str) -> bool:
    """Validate IPv4 address string.
    Returns True if s consists of four decimal numbers 0-255 separated by dots,
    with no leading zeros unless the number is exactly '0'.
    """
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for p in parts:
        # each part must be non-empty and all digits
        if not p or not p.isdigit():
            return False
        # no leading zeros unless single zero
        if len(p) > 1 and p[0] == '0':
            return False
        # range check
        val = int(p)
        if not (0 <= val <= 255):
            return False
    return True

