def solve(tokens):
    """Evaluate Reverse Polish Notation expression with integer arithmetic.
    Supports '+', '-', '*', '/' where division truncates toward zero.
    Tokens are strings representing integers (may be negative) or operators.
    """
    stack = []
    for t in tokens:
        if t in {'+', '-', '*', '/'}:
            b = stack.pop()
            a = stack.pop()
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:  # division truncating toward zero
                # avoid division by zero; assume input avoids it
                sign = -1 if (a < 0) ^ (b < 0) else 1
                stack.append(sign * (abs(a) // abs(b)))
        else:
            stack.append(int(t))
    return stack[0] if stack else 0

