    # Convert base to integer safely
    try:
        b_int = int(b)
    except Exception:
        return ""
    if b_int < 2 or b_int > 36:
        return ""
    # Convert number to integer safely
    try:
        n_int = int(n)
    except Exception:
        return ""
    if n_int == 0:
        return "0"
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    neg = n_int < 0
    n_int = -n_int if neg else n_int
    res = []
    while n_int:
        n_int, rem = divmod(n_int, b_int)
        res.append(digits[rem])
    if neg:
        res.append('-')
